  "settings.cloudListensHint": "將此伺服器的聆聽記錄加入您帳號的「我的聆聽」頁面，與您其他 Tune 伺服器的記錄合併。每筆聆聽記錄包含：日期、時長、不透明的個人檔案識別碼、標題、演出者、專輯，以及已知時的 ISRC 與 MusicBrainz 識別碼。絕不包含您的檔案路徑、IP 位址或區域名稱。預設為關閉。",
