  "settings.communityShare": "與社群分享我的評分與聆聽記錄（匿名）",
  "settings.communityShareHint": "與「我的聆聽」各自獨立，預設為關閉。您的專輯評分（不含評論）以及開啟此選項「之後」帳號收到的聆聽記錄，會納入公開的匿名統計，在有三位不同的人參與後顯示於專輯頁面上。絕不會顯示任何個人資料。關閉此選項會立即移除您的貢獻。",
  "settings.communityMeasuresReceive": "接收來自社群的分析結果",
  "settings.communityMeasuresReceiveHint": "預設為關閉。對於您的 FLAC 檔案，伺服器會向 mozaiklabs.fr 索取由至少兩部其他安裝在完全相同的訊號上已量測過的 ReplayGain、動態範圍與聲學指紋。這些資料只會填補缺少的部分：絕不會取代您的標籤與您自己的量測結果。網站只會收到一段簡短的前綴，絕不會收到您的檔案清單。",
  "settings.communityMeasuresContribute": "與社群分享我的分析結果",
  "settings.communityMeasuresContributeHint": "預設為關閉。伺服器只會將它自己對您的 FLAC 檔案所做的量測（ReplayGain、動態範圍、聲學指紋）傳送至網站，並以其訊號的簽章作為識別。不會傳送任何路徑、標題、檔案名稱或帳號：伺服器以其安裝編號識別自己。關閉此選項會清除已傳送的內容。",
