  "upsampling.eyebrow": "Premium 外掛程式",
  "upsampling.title": "升頻",
  "upsampling.lead": "在本機輸出上，依循來源的取樣率家族（44.1 → 352.8 kHz、48 → 384 kHz），將取樣率提升至 DAC 可接受的最高值。音量會降低 3 dB，並由安全限幅器壓住極少數剩餘的峰值：完全不會削波。Tune 的音量會補回這 3 dB：只要音量在 −3 dB 或以下，音量就與未升頻時相同（音量為 100% 時，請在 DAC 或前級上調整音量）。",
  "upsampling.noZone": "請選擇一個區域以設定其升頻。",
  "upsampling.bitPerfect": "啟用時，升頻會改變每個取樣：訊號路徑將不再是位元完美（bit-perfect）。PURE 模式一律會略過升頻，DoP 串流也絕不會被升頻。",
  "upsampling.enabled": "對此區域升頻",
  "upsampling.enabledHint": "預設為關閉。僅限本機輸出，且 DAC 的取樣率已經量測。在 macOS 與 Windows 上僅限共用模式（不支援獨佔模式與 ASIO）；在 Linux 上也支援 hw: 直接輸出。原生 DSD 與已完整解碼的壓縮串流不會被升頻。",
  "upsampling.filter": "濾波器",
  "upsampling.filterHint": "只會提供這部機器能即時執行（保留 ×3 餘裕）的濾波器。括號內：音量降低幅度。",
  "upsampling.filterNotAdmitted": "這部機器無法即時執行此濾波器：將不會套用。請選擇其他濾波器，或重新量測機器。",
  "upsampling.target": "目標取樣率",
  "upsampling.targetHint": "來源取樣率的整數倍，絕不超過 DAC 可接受的範圍。",
  "upsampling.targetMax": "DAC 最大值",
  "upsampling.dither": "抖動（dither）",
  "upsampling.ditherHint": "使用輸出本身的抖動，於降低位元深度時套用：TPDF，不含雜訊整形。",
  "upsampling.machine": "機器測試",
