  "pareFeu.titre": "Windows 防火牆正在此網路上過濾 Tune",
  "pareFeu.corps": "目前使用的網路被歸類為「{profils}」，而 Tune 的防火牆規則並未涵蓋此類網路。因此，UPnP/DLNA 裝置的探索以及從手機存取都會被封鎖：某些裝置可能只會以 AirPlay 形式出現，或完全收不到任何內容。",
  "pareFeu.etapePrive": "將網路設為「私人」：Windows 設定 ▸ 網路和網際網路 ▸ 網路內容 ▸ 網路個人檔案類型：私人。",
  "pareFeu.etapeAutoriser": "或允許 Tune 在此網路上通訊：Windows 安全性 ▸ 防火牆與網路保護 ▸ 允許應用程式通過防火牆 ▸ tune-server.exe。",
  "pareFeu.etapeRedemarrer": "然後重新啟動 Tune。",
  "pareFeu.profilDomaine": "網域",
  "pareFeu.profilPrive": "私人",
  "pareFeu.profilPublic": "公用",
  "pareFeu.corpsBlocage": "有一條防火牆規則在此網路（{profils}）上封鎖了 tune-server.exe：{regles}。它的優先順序高於「允許應用程式通過防火牆」中勾選的權限，且不會出現在該處。因此，UPnP/DLNA 裝置的探索以及從手機存取仍會被封鎖。",
  "pareFeu.etapeSupprimerBlocage": "刪除所有名為 {regles} 的封鎖規則（通常有兩條：TCP 與 UDP）：Windows Defender 防火牆 ▸ 進階設定 ▸ 輸入規則 ▸ 帶有封鎖圖示的規則 ▸ 刪除。",
  "pareFeu.corpsAutreChemin": "Tune 已獲防火牆允許，但允許的是與目前執行之程式不同的位置。因此在此網路（{profils}）上，UPnP/DLNA 裝置的探索以及從手機存取都會被封鎖。",
